head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf30001";
scwin.panel_hidden_values = null;
scwin.Grd_com_isur = null;
scwin.btn_ISUR_CD = null;
scwin.btn_VIEWDSCL = null;
scwin.txa_Remk = null;
scwin.panel_key_values = null;
scwin.btn_Multi = null;
scwin.btn_Delete = null;
scwin.gParamObj = undefined;
scwin.dts_Schedule = null;
scwin.dts_Charge2_Info = null;
scwin.dts_Status = null;
scwin.MxDataSet_com_isur = null;
scwin.gDepCd = undefined;
scwin.gEmpNo = undefined;
scwin.gLdMktTp = undefined;
scwin.gMarket = undefined;
scwin.strDepCd = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        scwin.hideDebugCtrls();
        scwin.resizeToWin();
        scwin.moveWin();
        await scwin.tx_script_dts_Status();
        await scwin.getParam();
        fn_com_isur(ipt_txb_ISUR_CD, ipt_txb_COM_NM);  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_com_isur — as-is 공통(폼 전역 의존) — 반입 보류

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30001.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.gDepCd =$c.session.getUserInfo("depCd"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30001' }); }

try { scwin.gEmpNo =$c.session.getUserInfo("empNo"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30001' }); }

try { scwin.gLdMktTp =$c.session.getUserInfo("market"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30001' }); }

try { scwin.gMarket =$c.session.getUserInfo("market"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30001' }); }

try { scwin.strDepCd =$c.session.getUserInfo("depCd").substring(0,2); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30001' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.panel_hidden_values = $c.util.getComponent('panel_hidden_values');
        scwin.Grd_com_isur = $c.util.getComponent('Grd_com_isur');
        scwin.btn_ISUR_CD = $c.util.getComponent('btn_ISUR_CD');
        scwin.btn_VIEWDSCL = $c.util.getComponent('btn_VIEWDSCL');
        scwin.txa_Remk = $c.util.getComponent('txa_Remk');
        scwin.panel_key_values = $c.util.getComponent('panel_key_values');
        scwin.btn_Multi = $c.util.getComponent('btn_Multi');
        scwin.btn_Delete = $c.util.getComponent('btn_Delete');
        scwin.dts_Schedule = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Schedule')) : $c.util.getComponent('dts_Schedule');
        scwin.dts_Charge2_Info = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Charge2_Info')) : $c.util.getComponent('dts_Charge2_Info');
        scwin.dts_Status = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Status')) : $c.util.getComponent('dts_Status');
        scwin.MxDataSet_com_isur = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('MxDataSetComIsur')) : $c.util.getComponent('MxDataSetComIsur');
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf30001.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Close_onclick
 * @description btn_Close 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame
    try {
        $c.win.closePopup();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30001.btn_Close_onclick' }); }
};

/**
 * @method
 * @name btn_Search_Rpt_Nm_onclick
 * @description btn_Search_Rpt_Nm 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_Rpt_Nm_onclick = async function () {
    try {
        await scwin.openDiscls();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf30001.btn_Search_Rpt_Nm_onclick' }); }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description btn_Save 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Save_onclick = async function () {
    try {
        await scwin.sbm_trs_Save();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30001.btn_Save_onclick' }); }
};

/**
 * @method
 * @name trs_Save_onfail
 * @description trs_Save onfail 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_onfail = function () {
    try {
        $c.win.alert(trs_Save);
        scwin.dts_Schedule.removeAll();
        (scwin.dts_Schedule.insertRow(), scwin.dts_Schedule.setRowPosition(scwin.dts_Schedule.getRowCount()-1));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf30001.trs_Save_onfail" });
    }
};

/**
 * @method
 * @name trs_Save_onsuccess
 * @description 알림을 띄운다 외
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_onsuccess = async function () {
    try {
        // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame, $c.frame.Provider, $c.frame.srcUrl
        await $c.win.alert($c.data.getMessage("MSG-A001", "저장"));
        const fr_fn_SearchMain = $c.win.getParent().fn_SearchMain;
        const isFnSrch = $c.util.getParameter($c.frame.srcUrl, "isFnSrch");
        if (isFnSrch === 'N') {
            $c.win.closePopup();
        } else {
            if (fr_fn_SearchMain == null) {
                const parentWin = $c.win.getParent();
                const parendID = $c.util.getParameter($c.frame.srcUrl, "frameid");
                const fr_fn_Search = parentWin.Provider(parendID).fn_Search;
                fr_fn_Search();
                $c.win.closePopup();
            } else {
                fr_fn_SearchMain();
                $c.win.closePopup();
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf30001.trs_Save_onsuccess" });
    }
};

/**
 * @method
 * @name btn_Adm_Itm_Tp_Cd_onclick
 * @description btn_Adm_Itm_Tp_Cd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Adm_Itm_Tp_Cd_onclick = function () {
    try {
        scwin.admItmTpCd();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30001.btn_Adm_Itm_Tp_Cd_onclick' }); }
};

/**
 * @method
 * @name dts_Schedule_onloadcompleted
 * @description dts_Schedule onloadcompleted 이벤트
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Schedule_onloadcompleted = async function (rowcount) {
    try {
        const vISUR_CD = scwin.dts_Schedule.getCellData(1, "ISUR_CD");
        const vLD_MKT_TP_CD = scwin.dts_Schedule.getCellData(1, "LD_MKT_TP_CD");
        if (vISUR_CD !== '' && vISUR_CD.length === 5) {
            await scwin.tx_script_dts_Charge2_Info(vISUR_CD, vLD_MKT_TP_CD);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf30001.dts_Schedule_onloadcompleted" });
    }
};

/**
 * @method
 * @name btn_ISUR_CD_onclick
 * @description btn_ISUR_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ISUR_CD_onclick = function () {
    try {
        if ($c.session.getUserInfo("depCd") === "11D0") {
            fn_SetPar = scwin.setParIsur2;
            scwin.popFindDigitalIsurAll();
        } else {
            IsurcdSearch(ipt_txb_ISUR_CD, ipt_txb_COM_NM);
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30001.btn_ISUR_CD_onclick' }); }
};

/**
 * @method
 * @name btn_VIEWDSCL_onclick
 * @description btn_VIEWDSCL 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_VIEWDSCL_onclick = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.fil.fn_OpenDisclViewer
    try {
        const AcptNo = scwin.dts_Schedule.getCellData(1, "ACPT_NO");
        if (AcptNo !== '') {
            $c.fil.fn_OpenDisclViewer(AcptNo, "R");
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30001.btn_VIEWDSCL_onclick' }); }
};

/**
 * @method
 * @name btn_Multi_onclick
 * @description btn_Multi 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Multi_onclick = function () {
    try {
        scwin.multi();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30001.btn_Multi_onclick' }); }
};

/**
 * @method
 * @name Grd_com_isur_onkeypress
 * @description Grd_com_isur onkeypress 이벤트
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_onkeypress = async function (kcode) {
    try {
        if (kcode === '13') {
            fn_com_Confirm_set();  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_com_Confirm_set — as-is 공통(폼 전역 의존) — 반입 보류
            await scwin.readChrgInfo2();
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30001.Grd_com_isur_onkeypress' }); }
};

/**
 * @method
 * @name Grd_com_isur_ondblclick
 * @description Grd_com_isur 더블클릭 이벤트
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_ondblclick = async function (row, colid) {
    try {
        fn_com_Confirm_set();  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_com_Confirm_set — as-is 공통(폼 전역 의존) — 반입 보류
        await scwin.readChrgInfo2();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30001.Grd_com_isur_ondblclick' }); }
};

/**
 * @method
 * @name Grd_com_isur_onclick
 * @description Grd_com_isur 의 onclick 에서 Grd_com_isur 을(를) 보이기를 바꾼다
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_onclick = function (row, colid) {
    try {
        scwin.Grd_com_isur.setStyle("display", "");

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30001.Grd_com_isur_onclick' }); }
};

/**
 * @method
 * @name Grd_com_isur_onsetfocus
 * @description Grd_com_isur onsetfocus 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_onsetfocus = function () {
    try {
        stFocusGrid = true;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30001.Grd_com_isur_onsetfocus' }); }
};

/**
 * @method
 * @name Grd_com_isur_onkillfocus
 * @description Grd_com_isur 을(를) 보이기를 바꾼다 외
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_onkillfocus = function () {
    try {
        stFocusGrid = false;
        scwin.Grd_com_isur.setStyle("display", "none");

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30001.Grd_com_isur_onkillfocus' }); }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function () {
    try {
        if (stFocusGrid === false) {
            scwin.Grd_com_isur.setStyle("display", "none");
        }
        if (ipt_txb_ISUR_CD.value === "") {
            $c.util.getComponent("ipt_txb_COM_NM").setValue("");
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30001.txb_ISUR_CD_onblur' }); }
};

/**
 * @method
 * @name txb_ISUR_CD_onfocus
 * @description txb_ISUR_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onfocus = function () {
    try {
        if (ipt_txb_ISUR_CD.readOnly === false) {
            scwin.Grd_com_isur.setStyle("display", "none");
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30001.txb_ISUR_CD_onfocus' }); }
};

/**
 * @method
 * @name txb_ISUR_CD_onkeyup
 * @description txb_ISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onkeyup = function () {
    try {
        if (ipt_txb_ISUR_CD.value === "") {
            scwin.Grd_com_isur.setStyle("display", "none");
        } else {
            if ($c.util.getKeyCode(event) === 40) {
                scwin.Grd_com_isur.Focus();
            } else {
                fn_com_isur_nm($c.util.getKeyCode(event));  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_com_isur_nm — as-is 공통(폼 전역 의존) — 반입 보류
            }
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30001.txb_ISUR_CD_onkeyup' }); }
};

/**
 * @method
 * @name MxDataSet_com_isur_onfilter
 * @description MxDataSet_com_isur onfilter 이벤트
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_onfilter = function (row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = scwin.MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = scwin.MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) {
                return true;
            } else {
                return false;
            }
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf30001.MxDataSet_com_isur_onfilter" });
    }
};

/**
 * @method
 * @name btn_Delete_onclick
 * @description btn_Delete 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Delete_onclick = async function () {
    try {
        await scwin.delete();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf30001.btn_Delete_onclick' }); }
};

/**
 * @method
 * @name txa_Remk_onchange
 * @description txa_Remk 변경 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txa_Remk_onchange = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.fil.getObjectValue
    try {
        ipt_txbTitleSize.setValue($c.str.getByteLength(scwin.txa_Remk.getValue()));
        if ($c.str.getByteLength(scwin.txa_Remk.getValue()) > 1500) {
            ipt_txbAlert.setValue('가 초과되었습니다.');
            scwin.txa_Remk.Focus();
            return;
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30001.txa_Remk_onchange' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_script_dts_Status
 * @description script dts Status 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_script_dts_Status = async function () {
    $c.util.getComponent("dma_scriptDts_StatusReq").set("inputMessageId", "CODEVALUE_INOUT");
    $c.util.getComponent("dma_scriptDts_StatusReq").set("outputMessageId", "CODE_OUT");
    $c.util.getComponent("dma_scriptDts_StatusReq").set("FOR", "C");
    $c.util.getComponent("dma_scriptDts_StatusReq").set("CD_ENG_NM", "DISCLS_SCHDL_ACT_STAT_CD");
    const sbmOptions = {
        id: "tx_script_dts_Status",
        method: "post",
        action: "/CodeAction.do",
        ref: "dma_scriptDts_StatusReq",
        target: "dts_Status=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_Status_onloaderror'] === 'function') ? scwin['dts_Status_onloaderror'] : (typeof scwin['dts_Status_onfail'] === 'function') ? scwin['dts_Status_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_Status_onloadcompleted'] === 'function') ? scwin['dts_Status_onloadcompleted'] : ((typeof scwin['dts_Status_onsuccess'] === 'function') ? scwin['dts_Status_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dts_Status'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf30001.tx_script_dts_Status" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name tx_script_dts_Charge2_Info
 * @description script dts Charge2 Info 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_script_dts_Charge2_Info = async function () {
    $c.util.getComponent("dma_scriptDts_Charge2_InfoReq").set("Flag", "4");
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "보낼 입력값을 아직 읽지 못합니다(전환 미완) — ISUR_CD, MKT_TP_CD"
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — ISUR_CD, MKT_TP_CD", unresolved: "query_param:ISUR_CD,MKT_TP_CD" };
    const sbmOptions = {
        id: "tx_script_dts_Charge2_Info",
        method: "post",
        action: "/ListedCompany.do",
        ref: "dma_scriptDts_Charge2_InfoReq",
        target: "dts_Charge2_Info=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_Charge2_Info_onloaderror'] === 'function') ? scwin['dts_Charge2_Info_onloaderror'] : (typeof scwin['dts_Charge2_Info_onfail'] === 'function') ? scwin['dts_Charge2_Info_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_Charge2_Info_onloadcompleted'] === 'function') ? scwin['dts_Charge2_Info_onloadcompleted'] : ((typeof scwin['dts_Charge2_Info_onsuccess'] === 'function') ? scwin['dts_Charge2_Info_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dts_Charge2_Info'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf30001.tx_script_dts_Charge2_Info" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_script_dts_Schedule
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
