/**
 * @method
 * @name getParam
 * @description get Param 처리
 * @returns {void}
 * @hidden N
 */
scwin.getParam = async function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.Provider, $c.frame.srcUrl
    const parentWin = $c.win.getParent();
    const src = $c.util.getParameter($c.frame.srcUrl, "src");
    if (src === "JSP") {
        const cmd = $c.util.getParameter($c.frame.srcUrl, "cmd");
        if (cmd === "C") {
            await scwin.tx_script_dts_Schedule();
        } else {
            const vDiscls_schdl_adm_dd = $c.util.getParameter($c.frame.srcUrl, "discls_schdl_adm_dd");
            const vBydd_seq = $c.util.getParameter($c.frame.srcUrl, "bydd_seq");
            const vInteg_usr_id = $c.util.getParameter($c.frame.srcUrl, "integ_usr_id");
            ipt_txb_Cmd.setValue(cmd);
            ipt_txb_DISCLS_SCHDL_ADM_DD.setValue(vDiscls_schdl_adm_dd);
            ipt_txb_BYDD_SEQ.setValue(vBydd_seq);
            ipt_txb_INTEG_USR_ID.setValue(vInteg_usr_id);
            scwin.btn_VIEWDSCL.show("");
            await scwin.tx_script_dts_Schedule();
            scwin.btn_ISUR_CD.hide();
            scwin.btn_Delete.show("");
            $c.util.getComponent('ipt_txb_ISUR_CD').setReadOnly(true);
        }
    } else {
        const paramObj = parentWin.gParamObj;
        ipt_txb_Cmd.setValue(paramObj.param0);
        ipt_txb_DISCLS_SCHDL_ADM_DD.setValue(paramObj.param1);
        ipt_txb_BYDD_SEQ.setValue(paramObj.param2);
        ipt_txb_INTEG_USR_ID.setValue(paramObj.param3);
        if (paramObj.param0 == null || paramObj.param0 == null || paramObj.param0 === "" || paramObj.param0 === "C") {
            await scwin.tx_script_dts_Schedule();
            scwin.btn_VIEWDSCL.hide();
        } else {
            if (paramObj.param0 === "R") {
                await scwin.tx_script_dts_Schedule();
                scwin.btn_ISUR_CD.hide();
                scwin.btn_Delete.show("");
                $c.util.getComponent('ipt_txb_ISUR_CD').setReadOnly(true);
            }
        }
    }
};

