    scwin.gParamObj = new Array(argc);
    for (let i = 0; i < argc; i++) {
        scwin.gParamObj["param" + i] = argv[i];
    }
    return true;
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function () {
    if (rd_rdo_Market_Flag.getValue() === "") {
        await $c.win.alert("[시장구분]을 선택하세요.");
        $c.util.getComponent("rd_rdo_Market_Flag").focus();
        return false;
    }
    if (js_sndloc === '13' && ipt_txb_COM_NM.getValue() === "") {
        await $c.win.alert("[회사코드]을 선택하세요.");
        $c.util.getComponent("ipt_txb_COM_NM").focus();
        return false;
    }
    if (cal_edt_Deadline.getValue() === "") {
        await $c.win.alert("[관리기한]을 선택하세요.");
        $c.util.getComponent("cal_edt_Deadline").focus();
        return false;
    }
    if (ipt_txb_SCHDL_ADM_ITM_TP_NM.getValue() === "") {
        await $c.win.alert("[관리항목]을 선택하세요.");
        $c.util.getComponent("ipt_txb_SCHDL_ADM_ITM_TP_NM").focus();
        return false;
    }
    if (slc_cmb_Status.getValue() === "") {
        await $c.win.alert("[일정상태]을 선택하세요.");
        $c.util.getComponent("slc_cmb_Status").focus();
        return false;
    }
    if (scwin.txa_Remk.getValue() === "") {
        await $c.win.alert("[비고]을 입력하세요.");
        scwin.txa_Remk.focus();
        return false;
    }
    if ($c.session.getUserInfo("market") === "2" && scwin.gDepCd !== '3220' || $c.session.getUserInfo("market") === "6") {
        if (slc_cmb_Confirm.getValue() === "") {
            await $c.win.alert("[확정여부]를 선택하세요.");
            $c.util.getComponent("slc_cmb_Confirm").focus();
            return false;
        }
    }
    if ($c.session.getUserInfo("market") === "2") {
        if (scwin.gDepCd !== '3220' && slc_cmb_SMS.getValue() === "") {
            await $c.win.alert("SMS 전송여부를 선택하세요.");
            $c.util.getComponent("slc_cmb_SMS").focus();
            return false;
        }
    }
    if ($c.fil.checkMaxLength(scwin.txa_Remk, 1500, "비고")) {
        return true;
    }
};

